Metadata: {"concept":"Goods pass between several caravans and market towns across branching routes, showing the Silk Road as a relay network rather than one continuous journey.","primary_subject":"silk_road_trade_network","secondary_subjects":["camel_caravans","linked_market_towns"],"visual_keywords":[],"composition_hints":["asymmetric_composition","layered_scene"],"scene_type":"diagram","mood":"neutral","palette":"terracotta_cream"}
